// Community-contributions section for a cookbook model page — the config as
// contributed plus a link to the PR. Renders as a carousel, one contribution per slide.
//
// Data: `configs/<org>/<model>-community.jsx`, GENERATED by
// docs/scripts/gen_community_entry.mjs. Shape + rationale: cookbook-add-model skill,
// authoring-reference.md 2.5.
//
//   source   {label, url, author, org?, authorUrl?}
//   configs  [{id, title, hardware, modelName, sglangVersion, dockerImage?, env, flags}]
//
// The GPU count and the knob line are computed from `flags` — there is no `summary`
// field, so display text cannot drift from the command.
//
// Mintlify: no module-level statements, lowercase HTML tags only, no snippet imports
// (config arrives as a prop). Same constraints as _deployment.jsx.
export const CommunityConfigs = ({ community, config }) => {
  // ==== 1. Style helper (dark-mode-aware) ====
  // Left border is violet, so the section reads as a third surface at a glance:
  // Deploy is red (#D45D44), Playground amber (#FB923C), Community violet.
  const makeStyles = (isDark) => ({
    container: {
      maxWidth: "900px", margin: "0 auto",
      display: "flex", flexDirection: "column", gap: "8px",
    },
    group: {
      border: `1px solid ${isDark ? "#374151" : "#e5e7eb"}`,
      borderLeft: `3px solid ${isDark ? "#A78BFA" : "#8B5CF6"}`,
      borderRadius: "4px",
      background: isDark ? "#1f2937" : "#fff",
      padding: "8px 12px",
      display: "flex", flexDirection: "column", gap: "6px",
      // `flex: 1` so every card fills its slide — the track stretches all slides to
      // the tallest, so cards end up identical.
      flex: 1, minWidth: 0, width: "100%", boxSizing: "border-box",
    },
    groupHead: {
      display: "flex", flexWrap: "wrap", alignItems: "baseline",
      justifyContent: "space-between", gap: "4px 10px",
    },
    who: {
      fontSize: "12px", fontWeight: 600,
      color: isDark ? "#e5e7eb" : "#111827",
    },
    whoMeta: {
      fontSize: "11px", fontWeight: 400,
      color: isDark ? "#9ca3af" : "#6b7280",
    },
    prLink: {
      fontSize: "11px", fontWeight: 600, flexShrink: 0,
      color: isDark ? "#C4B5FD" : "#6D28D9",
      textDecoration: "underline", textUnderlineOffset: "2px",
    },
    chipRow: { display: "flex", flexWrap: "wrap", gap: "4px" },
    chip: (active) => ({
      padding: "2px 10px", fontSize: "11px", fontWeight: 500, cursor: "pointer",
      borderRadius: "3px",
      border: `1px solid ${active ? "#8B5CF6" : (isDark ? "#4b5563" : "#d1d5db")}`,
      background: active ? "#8B5CF6" : (isDark ? "#1f2937" : "#fff"),
      color: active ? "#fff" : (isDark ? "#e5e7eb" : "#374151"),
      userSelect: "none",
    }),
    identity: {
      display: "flex", flexWrap: "wrap", alignItems: "center", gap: "2px 6px",
      fontSize: "11px", color: isDark ? "#9ca3af" : "#6b7280",
    },
    knobs: {
      fontSize: "11px", lineHeight: "1.4",
      color: isDark ? "#9ca3af" : "#6b7280",
    },
    commandWrap: {
      background: isDark ? "#111827" : "#f5f5f5",
      borderRadius: "6px",
      border: `1px solid ${isDark ? "#374151" : "#e5e7eb"}`,
      overflow: "hidden",
    },
    commandHeader: {
      display: "flex", flexWrap: "wrap", justifyContent: "space-between",
      alignItems: "center", gap: "6px 10px",
      padding: "6px 10px",
      borderBottom: `1px solid ${isDark ? "#374151" : "#e5e7eb"}`,
      background: isDark ? "#1f2937" : "#fafafa",
    },
    commandPre: {
      padding: "12px 16px",
      fontFamily: "'Menlo', 'Monaco', 'Courier New', monospace",
      fontSize: "12px", lineHeight: "1.5",
      color: isDark ? "#e5e7eb" : "#374151",
      whiteSpace: "pre-wrap", overflowX: "auto", margin: 0,
      // Fits the longest realistic config; caps the uniform card height.
      maxHeight: "420px", overflowY: "auto",
    },
    // ---- carousel ----
    viewport: { overflow: "hidden" },
    track: (slide, animate) => ({
      display: "flex",
      transform: `translateX(-${slide * 100}%)`,
      transition: animate ? "transform 0.4s ease" : "none",
    }),
    slide: { flex: "0 0 100%", minWidth: 0, display: "flex" },
    nav: {
      display: "flex", alignItems: "center", justifyContent: "center", gap: "8px",
      paddingTop: "2px",
    },
    navBtn: {
      padding: "1px 8px", lineHeight: 1.3,
      border: `1px solid ${isDark ? "#4b5563" : "#d1d5db"}`,
      borderRadius: "4px",
      background: isDark ? "#1f2937" : "#fff",
      color: isDark ? "#e5e7eb" : "#374151",
      fontSize: "13px", cursor: "pointer",
    },
    dot: (active) => ({
      width: active ? "18px" : "6px", height: "6px", borderRadius: "3px",
      background: active ? "#8B5CF6" : (isDark ? "#4b5563" : "#d1d5db"),
      cursor: "pointer", transition: "width 0.2s, background 0.2s",
    }),
    navCount: {
      fontSize: "10px", color: isDark ? "#6b7280" : "#9ca3af",
      fontVariantNumeric: "tabular-nums", minWidth: "56px", textAlign: "right",
    },
    iconButton: {
      padding: "4px 10px",
      border: `1px solid ${isDark ? "#4b5563" : "#d1d5db"}`,
      borderRadius: "4px",
      background: isDark ? "#1f2937" : "#fff",
      color: isDark ? "#e5e7eb" : "#374151",
      fontSize: "11px", fontWeight: 500, cursor: "pointer",
      display: "inline-flex", alignItems: "center", gap: "4px",
    },
    runModeWrap: {
      display: "inline-flex",
      border: `1px solid ${isDark ? "#4b5563" : "#d1d5db"}`,
      borderRadius: "10px", overflow: "hidden",
      fontSize: "11px", fontWeight: 600, userSelect: "none",
    },
    runModeChip: (active, last) => ({
      padding: "2px 10px", cursor: "pointer",
      background: active ? (isDark ? "#1f2937" : "#fff") : "transparent",
      color: active
        ? (isDark ? "#e5e7eb" : "#111827")
        : (isDark ? "#9ca3af" : "#6b7280"),
      ...(last ? {} : { borderRight: `1px solid ${isDark ? "#4b5563" : "#d1d5db"}` }),
    }),
    empty: {
      padding: "12px", borderRadius: "4px", fontSize: "12px",
      color: isDark ? "#9ca3af" : "#6b7280",
      border: `1px dashed ${isDark ? "#374151" : "#e5e7eb"}`,
    },
    cta: {
      padding: "2px 12px", fontSize: "12px",
      color: isDark ? "#9ca3af" : "#6b7280",
      display: "flex", flexWrap: "wrap", alignItems: "center", gap: "6px",
    },
    ctaButton: {
      background: "transparent", border: "none", padding: 0,
      color: isDark ? "#C4B5FD" : "#6D28D9",
      cursor: "pointer", fontSize: "12px", fontWeight: 600,
      textDecoration: "underline", textUnderlineOffset: "2px",
    },
  });

  // ==== 2. Pure helpers ====
  const flagValue = (flags, name) => {
    for (const f of flags || []) {
      const parts = f.trim().split(/[\s=]+/);
      if (parts[0] === name) return parts.length > 1 ? parts.slice(1).join(" ") : true;
    }
    return undefined;
  };
  const flagInt = (flags, name, dflt) => {
    const n = parseInt(flagValue(flags, name), 10);
    return Number.isFinite(n) ? n : dflt;
  };

  // tp × nnodes. Absent --tp means tp=1 (sglang's default), not 8.
  const gpuCountOf = (flags) =>
    flagInt(flags, "--tp", flagInt(flags, "--tp-size", 1)) * flagInt(flags, "--nnodes", 1);

  // Distinguishing knobs, fixed order so two configs are comparable.
  const describeFlags = (flags) => {
    const parts = [];
    const str = (name) => {
      const v = flagValue(flags, name);
      return typeof v === "string" ? v : null;
    };
    const quant = str("--quantization");
    if (quant) parts.push(quant.toUpperCase());
    const specAlgo = str("--speculative-algorithm");
    if (specAlgo) {
      const triple = [
        str("--speculative-num-steps"),
        str("--speculative-eagle-topk"),
        str("--speculative-num-draft-tokens"),
      ];
      parts.push(specAlgo + (triple.every(Boolean) ? ` ${triple.join("-")}` : ""));
    }
    if (flagValue(flags, "--enable-prefill-cp")) {
      const cp = str("--attn-cp-size");
      parts.push("prefill CP" + (cp || ""));
    }
    if (flagValue(flags, "--enable-dp-attention")) {
      const dp = str("--dp") || str("--dp-size");
      parts.push("DP attention" + (dp ? ` ${dp}` : ""));
    }
    if (flagValue(flags, "--enable-ep-moe")) parts.push("EP MoE");
    const mfs = str("--mem-fraction-static");
    if (mfs) parts.push(`mem-fraction ${mfs}`);
    const mrr = str("--max-running-requests");
    if (mrr) parts.push(`max-running ${mrr}`);
    const cpfs = str("--chunked-prefill-size");
    if (cpfs) parts.push(`chunked-prefill ${cpfs}`);
    return parts;
  };

  const PLACEHOLDER_FALLBACKS = { HOST_IP: "0.0.0.0", PORT: "30000" };

  const placeholderDefaults = (schema) => {
    const out = { ...PLACEHOLDER_FALLBACKS };
    for (const [key, spec] of Object.entries(schema || {})) {
      if (spec && spec.default != null) out[key] = spec.default;
    }
    return out;
  };

  const interpolate = (text, envValues, modelName) =>
    (text || "").replace(/\{\{(\w+)\}\}/g, (m, key) => {
      if (key === "MODEL_NAME") return modelName || m;
      return envValues[key] != null && envValues[key] !== "" ? envValues[key] : m;
    });

  // Simplified vs _deployment.jsx: no overlay composition, multi-node splicing, or PD
  // port rewrite. A config needing those belongs in the matrix.
  const renderCommand = (cfg, envValues, mode) => {
    const flags = cfg.flags || [];
    const env = cfg.env || [];
    if (mode === "docker") {
      const image = cfg.dockerImage || "lmsysorg/sglang:latest";
      const portFlag = flags.find((f) => f.split(/[\s=]/)[0] === "--port");
      const servePort = portFlag ? portFlag.slice("--port".length).trim() : "{{PORT}}";
      return interpolate([
        "docker run --gpus all",
        "  --shm-size 32g",
        `  -p ${servePort}:${servePort}`,
        "  -v ~/.cache/huggingface:/root/.cache/huggingface",
        ...env.map((e) => `  --env ${e}`),
        "  --ipc=host",
        `  ${image}`,
        "  sglang serve",
        ...flags.map((f) => "    " + f),
      ].join(" \\\n"), envValues, cfg.modelName);
    }
    const envBlock = env.length ? env.join(" \\\n") + " \\\n" : "";
    return interpolate(
      `${envBlock}sglang serve \\\n${flags.map((f) => "  " + f).join(" \\\n")}`,
      envValues, cfg.modelName);
  };

  // ==== 3. React state + effects ====
  const [isDark, setIsDark] = useState(false);
  useEffect(() => {
    const check = () => {
      const html = document.documentElement;
      setIsDark(
        html.classList.contains("dark") ||
          html.getAttribute("data-theme") === "dark" ||
          html.style.colorScheme === "dark"
      );
    };
    check();
    const observer = new MutationObserver(check);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme", "style"],
    });
    return () => observer.disconnect();
  }, []);

  // Same localStorage key the Deploy panel's Env dialog writes, so HOST_IP / PORT agree
  // across the page. Read-only here — this section has no Env UI.
  const [env, setEnv] = useState(() => placeholderDefaults(config && config.placeholders));
  useEffect(() => {
    try {
      const raw = window.localStorage.getItem("sglang-deploy-env");
      if (raw) {
        setEnv({
          ...placeholderDefaults(config && config.placeholders),
          ...JSON.parse(raw),
        });
      }
    } catch {}
  }, []);

  const groups = community || [];
  // Which config is selected within each contribution, keyed by the PR label.
  const [picked, setPicked] = useState({});
  const [runModes, setRunModes] = useState({});
  const [copiedId, setCopiedId] = useState(null);

  // ---- carousel: one contribution visible at a time ----
  const [slide, setSlide] = useState(0);
  // Hover pauses; `stopped` is permanent — these panels hold a command a reader may be
  // mid-copy of, so any interaction ends autoplay for the session.
  const [hovering, setHovering] = useState(false);
  const [stopped, setStopped] = useState(false);
  // Suppresses the transition on the initial deep-link jump.
  const [animate, setAnimate] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  useEffect(() => {
    try {
      const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
      const apply = () => setReducedMotion(mq.matches);
      apply();
      mq.addEventListener("change", apply);
      return () => mq.removeEventListener("change", apply);
    } catch {}
  }, []);

  const AUTOPLAY_MS = 5000;
  const autoplaying = groups.length > 1 && !stopped && !hovering && !reducedMotion;
  useEffect(() => {
    if (!autoplaying) return;
    const t = setTimeout(() => {
      setAnimate(true);
      setSlide((i) => (i + 1) % groups.length);
    }, AUTOPLAY_MS);
    return () => clearTimeout(t);
  }, [autoplaying, slide, groups.length]);

  const goTo = (i) => {
    setStopped(true);
    setAnimate(true);
    setSlide((i + groups.length) % groups.length);
  };

  // Deep link: #community-<config id> selects that config inside its group.
  useEffect(() => {
    const hydrate = () => {
      const hash = (window.location.hash || "").replace(/^#/, "");
      if (!hash.startsWith("community-")) return;
      const id = hash.slice("community-".length);
      for (const [gi, g] of groups.entries()) {
        if ((g.configs || []).some((c) => c.id === id)) {
          // A deep link is an explicit destination; do not slide away from it.
          setStopped(true);
          setSlide(gi);
          setPicked((prev) => ({ ...prev, [groupKey(g)]: id }));
          return;
        }
      }
    };
    hydrate();
    window.addEventListener("hashchange", hydrate);
    return () => window.removeEventListener("hashchange", hydrate);
  }, []);

  const s = makeStyles(isDark);
  const groupKey = (g) => (g.source && g.source.url) || (g.source && g.source.label) || "";

  const copy = (id, text) => {
    setStopped(true);   // never slide away from a panel being copied
    try {
      navigator.clipboard.writeText(text);
      setCopiedId(id);
      setTimeout(() => setCopiedId(null), 1500);
    } catch {}
  };

  // ==== 4. JSX render ====
  const renderGroup = (g, gi) => {
    const src = g.source || {};
    const configs = g.configs || [];
    if (configs.length === 0) return null;
    const key = groupKey(g) || `group-${gi}`;
    const cfg = configs.find((c) => c.id === picked[key]) || configs[0];
    const mode = runModes[cfg.id] || "python";
    const command = renderCommand(cfg, env, mode);
    const modes = cfg.dockerImage ? ["python", "docker"] : ["python"];
    const gpuCount = gpuCountOf(cfg.flags);
    const knobs = describeFlags(cfg.flags);

    return (
      <div key={key} id={`community-${cfg.id}`} style={{ ...s.group, scrollMarginTop: "104px" }}>
        <div style={s.groupHead}>
          <div style={s.who}>
            {src.authorUrl
              ? <a href={src.authorUrl} style={s.prLink} target="_blank" rel="noreferrer">{src.author}</a>
              : src.author}
            {src.org && <span style={s.whoMeta}> · {src.org}</span>}
            {g.reportedAt && <span style={s.whoMeta}> · {g.reportedAt}</span>}
          </div>
          {src.url && (
            <a href={src.url} style={s.prLink} target="_blank" rel="noreferrer">
              {src.label || "source"} ↗
            </a>
          )}
        </div>

        {/* Chips only when a PR contributed several configs. */}
        {configs.length > 1 && (
          <div style={s.chipRow}>
            {configs.map((c) => (
              <span
                key={c.id}
                style={s.chip(c.id === cfg.id)}
                role="tab"
                aria-selected={c.id === cfg.id}
                onClick={() => { setStopped(true); setPicked({ ...picked, [key]: c.id }); }}
              >
                {c.title}
              </span>
            ))}
          </div>
        )}

        {/* Identity + knobs, derived from flags. */}
        <div style={s.identity}>
          {configs.length === 1 && <span>{cfg.title}</span>}
          {cfg.hardware && <span>· {gpuCount}× {cfg.hardware}</span>}
          {cfg.modelName && <span>· <code>{cfg.modelName}</code></span>}
          {cfg.sglangVersion && <span>· sglang <code>{cfg.sglangVersion}</code></span>}
        </div>
        {knobs.length > 0 && <div style={s.knobs}>{knobs.join(" · ")}</div>}

        <div style={s.commandWrap}>
          <div style={s.commandHeader}>
            <div style={s.runModeWrap} role="tablist" aria-label="Output format">
              {modes.map((m, i) => (
                <span
                  key={m}
                  style={{
                    ...s.runModeChip(mode === m, i === modes.length - 1),
                    ...(modes.length === 1 ? { borderRadius: 7 } : {}),
                  }}
                  role="tab"
                  aria-selected={mode === m}
                  onClick={() => { setStopped(true); setRunModes({ ...runModes, [cfg.id]: m }); }}
                >
                  {m === "docker" ? "Docker" : "Python"}
                </span>
              ))}
            </div>
            <button style={s.iconButton} onClick={() => copy(cfg.id, command)}>
              {copiedId === cfg.id ? "✓ Copied" : "⧉ Copy"}
            </button>
          </div>
          <pre style={s.commandPre}>{command}</pre>
        </div>
      </div>
    );
  };

  return (
    <div
      // NOT "community-configs": Mintlify auto-generates a heading anchor from
      // `## Community Configs`, and a duplicate id would make in-page links resolve to
      // whichever node the browser found first. Same reason _deployment.jsx uses
      // "deployment-configurator" rather than "deployment".
      id="community-config-cards"
      style={{ ...s.container, scrollMarginTop: "104px" }}
      className="not-prose"
    >
      {groups.length === 0 && (
        <div style={s.empty}>
          No community configs for this model yet. Verified one on your hardware? Use the
          Playground's <strong>Submit ↗</strong> button.
        </div>
      )}

      {/* Slides stay mounted (translateX, not conditional render) so track height is
          stable and every deep-link anchor is in the DOM. */}
      {groups.length > 0 && (
        <div
          style={s.viewport}
          onMouseEnter={() => setHovering(true)}
          onMouseLeave={() => setHovering(false)}
          onFocus={() => setHovering(true)}
          onBlur={() => setHovering(false)}
          role="group"
          aria-label="Community contributions"
        >
          <div style={s.track(slide, animate && !reducedMotion)}>
            {groups.map((g, gi) => (
              <div
                key={groupKey(g) || `slide-${gi}`}
                style={s.slide}
                aria-hidden={gi !== slide}
              >
                {renderGroup(g, gi)}
              </div>
            ))}
          </div>
        </div>
      )}

      {groups.length > 1 && (
        <div style={s.nav}>
          <button
            type="button" style={s.navBtn} aria-label="Previous contribution"
            onClick={() => goTo(slide - 1)}
          >‹</button>
          {groups.map((g, gi) => (
            <span
              key={`dot-${gi}`}
              style={s.dot(gi === slide)}
              role="button"
              tabIndex={0}
              aria-label={`Contribution ${gi + 1}: ${(g.source && g.source.label) || ""}`}
              aria-current={gi === slide}
              onClick={() => goTo(gi)}
              onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") goTo(gi); }}
            />
          ))}
          <button
            type="button" style={s.navBtn} aria-label="Next contribution"
            onClick={() => goTo(slide + 1)}
          >›</button>
          {/* ⏸ so a stopped carousel doesn't read as broken. */}
          <span style={s.navCount}>
            {slide + 1} / {groups.length}{autoplaying ? "" : " ⏸"}
          </span>
        </div>
      )}

      <div style={s.cta}>
        <span>Ran this model on hardware that isn't in the matrix?</span>
        <button
          type="button"
          onClick={() => {
            const el = document.getElementById("playground");
            if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
          }}
          style={s.ctaButton}
        >
          Submit it from the Playground →
        </button>
      </div>
    </div>
  );
};
